// Real441940/441d80 classifiers. Spatial/unit queries and45ef00/renderer
// feedback are explicit boundaries. Native branch order and sentinel writes run.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNativeAttackClickOracle extends GhidraScript{
 static final long RET=0x12345000L,S=0x7fff0000L,U=0x5e30c8L,T=U+192;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}
 void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}
 void resume(EmulatorHelper e)throws Exception{long s=e.readRegister("ESP").longValue(),r=read(e,s,4);e.writeRegister("ESP",s+4);if(!e.run(toAddr(r),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int branch=0;branch<2;branch++)for(int s=0;s<512;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{
  e.writeMemory(toAddr(U),new byte[384]);int cls=branch==0?new int[]{0,15,16,17,18}[s%5]:s%3==0?2:1;put(e,U+0x7c,1,cls);put(e,U+0x30,1,branch==1&&s%5==0?22:4);put(e,U+0x31,1,4);put(e,T+0x31,1,new int[]{4,5}[s%2]);put(e,T+0x5e,1,s%3==0?0:255);put(e,T+0x5f,1,17);put(e,0x622d1a,2,1);put(e,0x622dc2,1,0);put(e,0x622cc0,4,1);put(e,0x62d5f4,2,(s&64)!=0?0xaec:0xadf);put(e,0x58687a,1,(s&128)!=0?1:0);put(e,0x635b50,2,600);put(e,0x635b5c,2,700);put(e,0x62dc00,4,111);put(e,0x62dc3c,4,222);put(e,0x62dc48,2,333);put(e,0x622cfc,4,400+s%30);put(e,0x622cfe,2,500+s%20);put(e,0x622cb8,4,0);put(e,0x58686b,1,0);
  for(long p:new long[]{RET,0x44f5d0,0x438950,0x411b90,0x41c3f0,0x44a660,0x41c290,0x43ea80,0x45afb0,0x438740,0x45ef00,0x441550,0x441600,0x4396a0})e.setBreakpoint(toAddr(p));e.writeRegister("ESP",S);put(e,S,4,RET);if(!e.run(toAddr(branch==0?0x441940:0x441d80),null,monitor))throw new Exception(e.getLastError());long queries=0;int events=0,opcode=0,x=0,y=0,z=0,icon=-1,clear=0,stops=0;
  while(e.readRegister("EIP").longValue()!=RET){if(++stops>25)throw new Exception("too many stops");long pc=e.readRegister("EIP").longValue(),cx=e.readRegister("ECX").longValue(),dx=e.readRegister("EDX").longValue(),sp=e.readRegister("ESP").longValue();int result=0;
   if(pc==0x44f5d0){queries=queries*10+1;int mode=s%8;boolean hit=mode>=1&&mode<=5;put(e,cx,4,mode==1?U:T);result=hit?0:1;}else if(pc==0x438950){queries=queries*10+2;put(e,cx,2,200+s%80);put(e,dx,2,300+s%70);}else if(pc==0x411b90){queries=queries*10+3;result=s%3==0?0:1;}else if(pc==0x41c3f0){queries=queries*10+4;put(e,cx,2,read(e,cx,2)+3);put(e,dx,2,read(e,dx,2)-5);put(e,read(e,sp+8,4),2,(s&2)!=0?1:0);result=(s&1)!=0?1:0;}else if(pc==0x44a660){queries=queries*10+5;result=(s&4)!=0?1:0;}else if(pc==0x41c290){queries=queries*10+6;put(e,cx,2,read(e,cx,2)+7);put(e,dx,2,read(e,dx,2)-11);result=(s&16)!=0?1:0;}else if(pc==0x43ea80){queries=queries*10+7;result=(s&8)!=0?1:0;}else if(pc==0x45afb0){queries=queries*10+8;result=(s&32)!=0?1:0;}else if(pc==0x438740){icon=(int)dx&65535;}else if(pc==0x45ef00){events++;opcode=(byte)read(e,0x56ed47,1);x=(short)read(e,0x62dc00,2);y=(short)read(e,0x62dc3c,2);z=(short)read(e,0x62dc48,2);}else if(pc==0x4396a0){clear++;}else if(pc==0x441600){result=1;}e.writeRegister("EAX",result);resume(e);
  }
  out.println("{\"branch\":"+branch+",\"scenario\":"+s+",\"events\":"+events+",\"opcode\":"+opcode+",\"x\":"+x+",\"y\":"+y+",\"z\":"+z+",\"icon\":"+icon+",\"clear\":"+clear+",\"feedback\":"+read(e,0x58686b,1)+",\"return\":"+(branch==0?(e.readRegister("EAX").intValue()&255):0)+",\"queries\":"+queries+"}");
 }finally{e.dispose();}}}}
}
